#include "pending_identity_handle_creation.h"
#include "live_reference_identity_registry.h"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8);if(argc!=2)return 2;std::ifstream f(argv[1],std::ios::binary);if(!f)throw std::runtime_error("missing oracle");auto word=[&](){uint32_t v=0;f.read(reinterpret_cast<char*>(&v),4);if(!f)throw std::runtime_error("short oracle");return v;};unsigned cases=0;
 for(unsigned sequence=0;sequence<64;++sequence){RecoveredReferenceHandleTableCandidate handles;RecoveredPendingReferenceRegistryCandidate pending;std::array<RecoveredPendingIdentityCandidate,12>liveIdentities{};auto resolve=[&](uint32_t h)->const RecoveredPendingIdentityCandidate*{return h<101||h>112||(h-101)%5==0?nullptr:&liveIdentities[h-101];};RecoveredLiveIdentityRegistryCandidate live(16);for(unsigned i=0;i<12;++i){liveIdentities[i]={i%4,i,sequence,0x12345678};live.insert(101+i,resolve);}uint32_t flags=0,notices=0,lastNotice=0xffffffffu,lastCount=0xffffffffu;
 for(unsigned step=0;step<64;++step){unsigned id=(step*13+sequence)%23;RecoveredPendingIdentityCandidate identity{id%4,id,sequence,0x12345678};uint32_t result=createRecoveredPendingIdentityHandleCandidate(identity,handles,pending,flags,[&](const auto&key){return live.find(key,resolve);},[&](uint32_t h){++notices;lastNotice=h;lastCount=0;for(const auto&bucket:pending.buckets())lastCount+=uint32_t(bucket.size());});
 std::array<uint32_t,7>state{result&0x7fffffffu,flags,handles.active(),uint32_t(handles.slots().size()),notices,lastNotice,lastCount};for(auto v:state)if(v!=word())throw std::runtime_error("native pending creation state mismatch");for(const auto&bucket:pending.buckets()){if(bucket.size()!=word())throw std::runtime_error("native pending bucket mismatch");for(const auto&e:bucket){std::array<uint32_t,9>actual{e.identity[0],e.identity[1],e.identity[2],e.identity[3],e.record.handle&0x7fffffffu,e.record.counts,e.record.flags,e.record.headAttribute,uint32_t(e.record.next)};for(auto v:actual)if(v!=word())throw std::runtime_error("native pending creation record mismatch");}}++cases;}}
 if(f.peek()!=std::char_traits<char>::eof())throw std::runtime_error("trailing oracle");std::cout<<"native_pending_live_handle_creation_matches="<<cases<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
